sys_script_include.script:
var CourseSystemUtils = Class.create();
CourseSystemUtils.prototype = {
    initialize: function() {
    },

	refQualInstructor: function(){
		let listOfProfessors = []
		let gr = new GlideRecord("sys_user_grmember");
		gr.addEncodedQuery("group=7981927e835b5210b469b3a6feaad3f9");
		gr.query();
		while(gr.next()){
			listOfProfessors.push(gr.user.sys_id.toString());
		}
		return "sys_idIN" + listOfProfessors.join(",");
	},

	refQualCourseSchedules: function(){
		let listOfRegistrationRequests = [];
		let grAllregistrationrequests = new GlideRecord("x_1593190_course_0_course_registration_request");
		grAllregistrationrequests.query();

		while(grAllregistrationrequests.next()){
			listOfRegistrationRequests.push({
				student_sys_id: grAllregistrationrequests.opened_by.sys_id.toString(),
				course_sys_id: grAllregistrationrequests.course_schedule.course.sys_id.toString(),
				course_schedule_sys_id: grAllregistrationrequests.course_schedule.sys_id.toString(),
				course_schedule_state: grAllregistrationrequests.state.toString()
			});
		}

		let listOfCourseSchedules = [];
		let grCourseSchedule = new GlideRecord("x_1593190_course_0_course_schedule");
		let grMyRegistrationRequests = new GlideRecord("x_1593190_course_0_course_registration_request");
		grMyRegistrationRequests.addQuery("opened_by", gs.getUserID());
		grMyRegistrationRequests.query();

		grCourseSchedule.addEncodedQuery("date>javascript:gs.endOfToday()^instructor!=javascript:gs.getUserID()");
		grCourseSchedule.query();

		while(grCourseSchedule.next()){
			let countOfRequests = listOfRegistrationRequests.filter(item => item.course_schedule_sys_id == grCourseSchedule.sys_id.toString() && item.course_schedule_state != "4");
			let countOfMyRequests = listOfRegistrationRequests.filter(item => item.student_sys_id == gs.getUserID().toString() && grCourseSchedule.course.sys_id.toString() == item.course_sys_id);
			if(countOfRequests.length < grCourseSchedule.vacancies && countOfMyRequests.length < 3){
				listOfCourseSchedules.push(grCourseSchedule.sys_id.toString());
			}
		}

		while(grMyRegistrationRequests.next()){
			listOfCourseSchedules = listOfCourseSchedules.filter(item => item != grMyRegistrationRequests.course_schedule.sys_id.toString());
		}



		return "sys_idIN" + listOfCourseSchedules.join(',');

	},

    type: 'CourseSystemUtils'
};
